const articles = $input.all()
  .map(item => item.json)
  .filter(article => article.title && article.pubDate)
  .sort((a, b) => {
    return new Date(b.pubDate) - new Date(a.pubDate);
  })
  .slice(0, 5);

const articlesText = articles.map((article, index) => `
ARTICLE ${index + 1}
Title: ${article.title}
Published: ${article.pubDate}
Link: ${article.link}
Content: ${article.contentSnippet || article.content || ""}
`).join("\n-------------------\n");

return [
  {
    json: {
      articleCount: articles.length,
      articlesText: articlesText
    }
  }
];
